/**
 * YAML String-Based Validator
 * Validates YAML syntax without full parser
 * Targets 5 error categories: indentation, quotes, delimiters, colons, list items
 * This is DISPOSABLE code for hypothesis validation
 */

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  coverage: {
    quoteChecks: number;
    indentationChecks: number;
    delimiterChecks: number;
    colonChecks: number;
    listItemChecks: number;
  };
}

export interface ValidationError {
  type: string;
  line: number;
  column: number;
  message: string;
  content: string;
}

/**
 * Main validation function
 * Checks YAML content for common syntax errors
 */
export function validateYAML(content: string): ValidationResult {
  const lines = content.split('\n');
  const errors: ValidationError[] = [];
  const coverage = {
    quoteChecks: 0,
    indentationChecks: 0,
    delimiterChecks: 0,
    colonChecks: 0,
    listItemChecks: 0
  };

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum];
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Check 1: Unclosed quotes
    const quoteErrors = validateQuotes(line, lineNum);
    errors.push(...quoteErrors);
    if (quoteErrors.length === 0) coverage.quoteChecks++;

    // Check 2: Indentation consistency (spaces, not tabs)
    const indentErrors = validateIndentation(line, lineNum, lines);
    errors.push(...indentErrors);
    if (indentErrors.length === 0) coverage.indentationChecks++;

    // Check 3: YAML delimiters (---, ...)
    const delimiterErrors = validateDelimiters(line, lineNum);
    errors.push(...delimiterErrors);
    if (delimiterErrors.length === 0) coverage.delimiterChecks++;

    // Check 4: Colon syntax (key: value)
    const colonErrors = validateColonSyntax(line, lineNum);
    errors.push(...colonErrors);
    if (colonErrors.length === 0) coverage.colonChecks++;

    // Check 5: List item formatting (- item)
    const listErrors = validateListItems(line, lineNum);
    errors.push(...listErrors);
    if (listErrors.length === 0) coverage.listItemChecks++;
  }

  return {
    valid: errors.length === 0,
    errors,
    coverage
  };
}

/**
 * HYP-1 CRITERION 1: Detect unclosed quotes in 100% of test cases
 */
function validateQuotes(line: string, lineNum: number): ValidationError[] {
  const errors: ValidationError[] = [];

  // Count quotes (simple matching - not escaped quotes)
  const singleQuotes = (line.match(/'/g) || []).length;
  const doubleQuotes = (line.match(/"/g) || []).length;

  // Odd number of quotes = unclosed
  if (singleQuotes % 2 !== 0) {
    errors.push({
      type: 'UNCLOSED_QUOTE',
      line: lineNum + 1,
      column: line.lastIndexOf("'") + 1,
      message: "Unclosed single quote",
      content: line
    });
  }

  if (doubleQuotes % 2 !== 0) {
    errors.push({
      type: 'UNCLOSED_QUOTE',
      line: lineNum + 1,
      column: line.lastIndexOf('"') + 1,
      message: "Unclosed double quote",
      content: line
    });
  }

  return errors;
}

/**
 * HYP-1 CRITERION 2: Detect indentation inconsistencies with 95%+ accuracy
 */
function validateIndentation(
  line: string,
  lineNum: number,
  lines: string[]
): ValidationError[] {
  const errors: ValidationError[] = [];

  if (line.length === 0 || !line[0].match(/\s/)) {
    return errors; // No indentation
  }

  // Check for tabs (not allowed in YAML)
  if (line.includes('\t')) {
    errors.push({
      type: 'INDENTATION_TAB',
      line: lineNum + 1,
      column: 1,
      message: "YAML uses spaces, not tabs",
      content: line
    });
  }

  // Check indentation consistency (should be multiples of 2 or 4)
  const leadingSpaces = line.match(/^( *)/)?.[1].length || 0;
  if (leadingSpaces > 0 && leadingSpaces % 2 !== 0) {
    // Warning: indentation not multiple of 2
    // This is common in some YAML styles, so we check context
    if (lineNum > 0) {
      const prevLine = lines[lineNum - 1];
      const prevIndent = prevLine.match(/^( *)/)?.[1].length || 0;

      // If previous line has different indent pattern, might be error
      if (Math.abs(leadingSpaces - prevIndent) > 4) {
        errors.push({
          type: 'INDENTATION_INCONSISTENT',
          line: lineNum + 1,
          column: leadingSpaces + 1,
          message: "Indentation inconsistent with previous lines",
          content: line
        });
      }
    }
  }

  return errors;
}

/**
 * HYP-1 CRITERION 3: Detect misplaced delimiters (---, ...) correctly
 */
function validateDelimiters(line: string, lineNum: number): ValidationError[] {
  const errors: ValidationError[] = [];
  const trimmed = line.trim();

  // Check for --- (document start) - should be on own line
  if (trimmed === '---') {
    return errors; // Valid
  }

  // Check for ... (document end) - should be on own line
  if (trimmed === '...') {
    return errors; // Valid
  }

  // If line contains --- but isn't just ---, it's misplaced
  if (line.includes('---') && trimmed !== '---') {
    errors.push({
      type: 'DELIMITER_MISPLACED',
      line: lineNum + 1,
      column: line.indexOf('---') + 1,
      message: "Document delimiter (---) must be on its own line",
      content: line
    });
  }

  // Same for ...
  if (line.includes('...') && trimmed !== '...') {
    errors.push({
      type: 'DELIMITER_MISPLACED',
      line: lineNum + 1,
      column: line.indexOf('...') + 1,
      message: "Document delimiter (...) must be on its own line",
      content: line
    });
  }

  return errors;
}

/**
 * HYP-1 CRITERION 4: Colon syntax (key: value pattern)
 */
function validateColonSyntax(line: string, lineNum: number): ValidationError[] {
  const errors: ValidationError[] = [];
  const trimmed = line.trim();

  // Skip delimiters and list items
  if (trimmed === '---' || trimmed === '...' || trimmed.startsWith('-')) {
    return errors;
  }

  // Check for colon not followed by space (in most cases)
  // Pattern: word: should have space after colon
  const colonMatch = trimmed.match(/:\S/);
  if (colonMatch && !trimmed.startsWith('http') && !trimmed.startsWith('ftp')) {
    // Skip URLs which are valid with colon
    const colonPos = line.indexOf(':');
    const charAfter = line[colonPos + 1];

    // If char after colon is not space or quote, might be error
    // But only if it looks like a key:value (not a URL)
    if (charAfter && !charAfter.match(/[\s"']/)) {
      // Check if line looks like key: value pattern
      const beforeColon = line.substring(0, colonPos).trim();
      if (beforeColon && beforeColon.match(/^\w+$/)) {
        // This looks like a malformed key: value
        errors.push({
          type: 'COLON_SYNTAX',
          line: lineNum + 1,
          column: colonPos + 1,
          message: "Colon should be followed by space (key: value)",
          content: line
        });
      }
    }
  }

  return errors;
}

/**
 * HYP-1 CRITERION 5: List item formatting (- item)
 */
function validateListItems(line: string, lineNum: number): ValidationError[] {
  const errors: ValidationError[] = [];
  const trimmed = line.trim();

  // Check for list item marker (-)
  if (trimmed.startsWith('-')) {
    // Should be: "- item" (dash followed by space)
    if (trimmed.length > 1 && trimmed[1] !== ' ' && trimmed[1] !== '\n') {
      errors.push({
        type: 'LIST_ITEM_FORMAT',
        line: lineNum + 1,
        column: 1,
        message: "List item should be '- ' (dash followed by space)",
        content: line
      });
    }
  }

  return errors;
}

/**
 * Calculate coverage percentage
 */
export function calculateCoverage(result: ValidationResult): number {
  const total = 5; // 5 check categories
  const checked =
    (result.coverage.quoteChecks > 0 ? 1 : 0) +
    (result.coverage.indentationChecks > 0 ? 1 : 0) +
    (result.coverage.delimiterChecks > 0 ? 1 : 0) +
    (result.coverage.colonChecks > 0 ? 1 : 0) +
    (result.coverage.listItemChecks > 0 ? 1 : 0);
  return (checked / total) * 100;
}

/**
 * Comprehensive test suite for HYP-1: String-based YAML validator coverage
 * Tests detection of: quotes, indentation, delimiters, colons, list items
 * Validates >90% coverage and real-world config files
 * This is DISPOSABLE test code for hypothesis validation
 */

import { validateYAML, ValidationResult } from './yaml-validator';

