/**
 * YAML syntax validator module.
 * Provides lightweight YAML syntax validation without external dependencies.
 */

/**
 * Represents a single validation error found in YAML content.
 */
export interface YamlError {
  line: number;
  column: number;
  message: string;
  type: "indentation" | "syntax" | "structure" | "delimiter";
  context?: string;
}

/**
 * Result of validating YAML content.
 */
export interface ValidationResult {
  valid: boolean;
  errors: YamlError[];
  fileSize?: number;
}

/**
 * Validate YAML content for syntax errors.
 * Checks for common structural issues: indentation, quote matching, delimiters, and key-value syntax.
 *
 * @param content - The YAML file content as a string
 * @param fileName - Optional filename for error context
 * @returns Validation result with error list
 */
export function validateYamlSyntax(
  content: string,
  fileName?: string
): ValidationResult {
  const lines = content.split("\n");
  const errors: YamlError[] = [];

  // Collect errors from all validation checks
  errors.push(...checkIndentation(lines));
  errors.push(...checkQuoteMatching(lines));
  errors.push(...checkDelimiters(lines));
  errors.push(...checkKeyValueSyntax(lines));

  // Remove duplicate errors (same line/column)
  const uniqueErrors = Array.from(
    new Map(errors.map((e) => [`${e.line}-${e.column}`, e])).values()
  );

  // Sort errors by line number
  uniqueErrors.sort((a, b) => a.line - b.line);

  return {
    valid: uniqueErrors.length === 0,
    errors: uniqueErrors,
    fileSize: content.length,
  };
}

/**
 * Check indentation consistency throughout the document.
 * Validates that indentation uses either 2-space or 4-space consistently.
 *
 * @param lines - Array of content lines
 * @returns Array of indentation errors
 */
function checkIndentation(lines: string[]): YamlError[] {
  const errors: YamlError[] = [];
  const indentPatterns: Set<number> = new Set();
  let expectedIndent: number | null = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Skip empty lines and lines with only whitespace
    if (line.trim().length === 0) {
      continue;
    }

    // Calculate indentation level (spaces at start)
    const match = line.match(/^( *)/);
    if (!match) {
      continue;
    }

    const indentCount = match[1].length;

    // Skip lines with no indentation
    if (indentCount === 0) {
      continue;
    }

    // Determine indent unit (2 or 4 spaces)
    const indentUnit = indentCount % 4 === 0 ? 4 : indentCount % 2 === 0 ? 2 : 0;

    if (indentUnit === 0) {
      // Invalid indentation (not a multiple of 2 or 4)
      errors.push({
        line: i + 1,
        column: indentCount + 1,
        message: `Invalid indentation: ${indentCount} spaces (must be multiple of 2)`,
        type: "indentation",
        context: line.trim().substring(0, 30),
      });
      continue;
    }

    indentPatterns.add(indentUnit);

    // Check if we have mixed indent styles
    if (indentPatterns.size > 1) {
      const patterns = Array.from(indentPatterns).sort();
      errors.push({
        line: i + 1,
        column: indentCount + 1,
        message: `Mixed indentation: found both ${patterns[0]}-space and ${patterns[1]}-space indents`,
        type: "indentation",
        context: line.trim().substring(0, 30),
      });
    }
  }

  return errors;
}

/**
 * Check that quotes (single and double) are properly matched.
 *
 * @param lines - Array of content lines
 * @returns Array of quote matching errors
 */
function checkQuoteMatching(lines: string[]): YamlError[] {
  const errors: YamlError[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    let inDouble = false;
    let inSingle = false;

    for (let col = 0; col < line.length; col++) {
      const char = line[col];

      // Skip escaped characters
      if (col > 0 && line[col - 1] === "\\") {
        continue;
      }

      if (char === '"' && !inSingle) {
        inDouble = !inDouble;
      } else if (char === "'" && !inDouble) {
        inSingle = !inSingle;
      }
    }

    // Check for unclosed quotes at end of line
    if (inDouble) {
      errors.push({
        line: i + 1,
        column: line.length,
        message: 'Unclosed double quote',
        type: "syntax",
        context: line.trim().substring(0, 30),
      });
    }

    if (inSingle) {
      errors.push({
        line: i + 1,
        column: line.length,
        message: "Unclosed single quote",
        type: "syntax",
        context: line.trim().substring(0, 30),
      });
    }
  }

  return errors;
}

/**
 * Validate YAML delimiters (---, ...) appear on their own lines.
 *
 * @param lines - Array of content lines
 * @returns Array of delimiter errors
 */
function checkDelimiters(lines: string[]): YamlError[] {
  const errors: YamlError[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Check for document start/end markers that aren't on their own line
    if ((trimmed === "---" || trimmed === "...") && line !== trimmed) {
      errors.push({
        line: i + 1,
        column: 1,
        message: `Document delimiter '${trimmed}' must be on its own line`,
        type: "delimiter",
        context: line.trim().substring(0, 30),
      });
    }

    // Check for malformed delimiters (e.g., ---- or ....)
    if (/^-{4,}/.test(trimmed) || /^\.{4,}/.test(trimmed)) {
      errors.push({
        line: i + 1,
        column: 1,
        message: `Invalid delimiter: '${trimmed.substring(0, 4)}...' (use '---' or '...')`,
        type: "delimiter",
        context: line.trim().substring(0, 30),
      });
    }
  }

  return errors;
}

/**
 * Check key-value pair syntax: colons must have space after them.
 *
 * @param lines - Array of content lines
 * @returns Array of key-value syntax errors
 */
function checkKeyValueSyntax(lines: string[]): YamlError[] {
  const errors: YamlError[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Skip empty lines and special lines
    if (trimmed.length === 0 || trimmed.startsWith("#")) {
      continue;
    }

    // Skip document markers and list items for now
    if (trimmed.startsWith("---") || trimmed.startsWith("...") || trimmed.startsWith("-")) {
      continue;
    }

    // Look for colons that aren't followed by space, newline, or quoted content
    for (let col = 0; col < trimmed.length; col++) {
      if (trimmed[col] === ":") {
        const nextChar = trimmed[col + 1];

        // Colon at end of line or followed by space is OK
        if (col === trimmed.length - 1 || nextChar === " " || nextChar === "\t") {
          continue;
        }

        // Check if we're inside a quoted string (skip validation)
        let inQuote = false;
        for (let j = 0; j < col; j++) {
          if (trimmed[j] === '"' || trimmed[j] === "'") {
            inQuote = !inQuote;
          }
        }

        if (!inQuote && nextChar !== undefined) {
          errors.push({
            line: i + 1,
            column: col + 1,
            message: "Colon must be followed by space in YAML",
            type: "syntax",
            context: trimmed.substring(0, 40),
          });
        }
      }
    }
  }

  return errors;
}

