import { describe, expect, test } from "bun:test";
import { validateYamlSyntax, type YamlError } from "./yaml-validator";

describe("yaml-validator", () => {
  // ============================================================================
  // Valid YAML Structure Tests
  // ============================================================================

  describe("valid YAML structures", () => {
    test("validates empty file", () => {
      const yaml = "";
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates simple key-value pair", () => {
      const yaml = "key: value";
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates nested map with 2-space indentation", () => {
      const yaml = `
key: value
nested:
  subkey: subvalue
  another: item
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates nested map with 4-space indentation", () => {
      const yaml = `
key: value
nested:
    subkey: subvalue
    another: item
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates list items with proper dashes", () => {
      const yaml = `
items:
  - first
  - second
  - third
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates document with start marker", () => {
      const yaml = `---
key: value
nested:
  subkey: subvalue
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates document with start and end markers", () => {
      const yaml = `---
key: value
nested:
  subkey: subvalue
...
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates values with quoted strings (double quotes)", () => {
      const yaml = `
title: "Hello World"
description: "A longer description"
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates values with quoted strings (single quotes)", () => {
      const yaml = `
title: 'Hello World'
description: 'A longer description'
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates deeply nested structure", () => {
      const yaml = `
level1:
  level2:
    level3:
      level4:
        level5: value
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates single line with no newline", () => {
      const yaml = "key: value";
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates comments in YAML", () => {
      const yaml = `
# This is a comment
key: value  # inline comment
# Another comment
nested:
  subkey: subvalue
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("validates empty lines between content", () => {
      const yaml = `
key: value

nested:
  subkey: subvalue

more: content
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });
  });

  // ============================================================================
  // Indentation Error Tests
  // ============================================================================

  describe("indentation error detection", () => {
    test("detects inconsistent indentation (3 spaces)", () => {
      const yaml = `
key: value
   nested: bad
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors.some((e) => e.type === "indentation")).toBe(true);
    });

    test("detects mixed 2-space and 4-space indentation", () => {
      const yaml = `
key: value
  nested2:
    nested4: value
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.type === "indentation")).toBe(true);
    });

    test("detects inconsistent indentation across multiple lines", () => {
      const yaml = `
root:
  child1: value1
   child2: value2
  child3: value3
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.type === "indentation")).toBe(true);
    });

    test("detects odd-number indentation (1 space)", () => {
      const yaml = `
key: value
 nested: bad
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.type === "indentation")).toBe(true);
    });

    test("detects odd-number indentation (5 spaces)", () => {
      const yaml = `
key: value
     nested: bad
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.type === "indentation")).toBe(true);
    });

    test("indentation error includes line number", () => {
      const yaml = `
key: value
   nested: bad
`;
      const result = validateYamlSyntax(yaml);
      const indentError = result.errors.find((e) => e.type === "indentation");
      expect(indentError).toBeDefined();
      expect(indentError?.line).toBe(3);
    });

    test("indentation error includes column number", () => {
      const yaml = `
key: value
   nested: bad
`;
      const result = validateYamlSyntax(yaml);
      const indentError = result.errors.find((e) => e.type === "indentation");
      expect(indentError).toBeDefined();
      expect(indentError?.column).toBeGreaterThan(0);
    });
  });

  // ============================================================================
  // Quote Matching Error Tests
  // ============================================================================

  describe("quote matching error detection", () => {
    test("detects unclosed double quote", () => {
      const yaml = `key: "unclosed`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("quote"))).toBe(true);
    });

    test("detects unclosed single quote", () => {
      const yaml = `key: 'unclosed`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("quote"))).toBe(true);
    });

    test("detects multiple unclosed quotes in different lines", () => {
      const yaml = `
key1: "unclosed1
key2: 'unclosed2
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThanOrEqual(2);
    });

    test("allows escaped quotes within strings", () => {
      const yaml = `key: "value with \\" escaped quote"`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("detects nested mismatched quotes", () => {
      const yaml = `
list:
  - "item with 'nested
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });

    test("quote error includes line number", () => {
      const yaml = `
key1: valid
key2: "unclosed
`;
      const result = validateYamlSyntax(yaml);
      const quoteError = result.errors.find((e) => e.message.includes("quote"));
      expect(quoteError?.line).toBe(3);
    });

    test("allows quotes in comments (not validated)", () => {
      const yaml = `
key: value
# Comment with "unclosed quote
another: value
`;
      const result = validateYamlSyntax(yaml);
      // Comment validation is minimal; focus on actual content
      expect(result.valid).toBe(true);
    });
  });

  // ============================================================================
  // Delimiter Validation Tests
  // ============================================================================

  describe("delimiter validation", () => {
    test("detects delimiter not on own line (start marker)", () => {
      const yaml = `--- key: value`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.type === "delimiter")).toBe(true);
    });

    test("detects delimiter not on own line (end marker)", () => {
      const yaml = `key: value ...`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.type === "delimiter")).toBe(true);
    });

    test("detects malformed start delimiter (4+ dashes)", () => {
      const yaml = `----
key: value
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.type === "delimiter")).toBe(true);
    });

    test("detects malformed end delimiter (4+ dots)", () => {
      const yaml = `
key: value
....
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.type === "delimiter")).toBe(true);
    });

    test("allows valid document start marker", () => {
      const yaml = `---
key: value
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("allows valid document end marker", () => {
      const yaml = `key: value
...
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("delimiter error includes line number", () => {
      const yaml = `
key: value
---- malformed
`;
      const result = validateYamlSyntax(yaml);
      const delimError = result.errors.find((e) => e.type === "delimiter");
      expect(delimError?.line).toBe(3);
    });
  });

  // ============================================================================
  // Key-Value Syntax Tests
  // ============================================================================

  describe("key-value syntax validation", () => {
    test("detects colon without space after it", () => {
      const yaml = `key:value`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("Colon"))).toBe(true);
    });

    test("detects multiple colons without space", () => {
      const yaml = `
key1:value1
key2:value2
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThanOrEqual(2);
    });

    test("allows colon at end of line (empty value)", () => {
      const yaml = `
key:
  nested: value
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("allows colon with space after", () => {
      const yaml = `key: value`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("allows colon with tab after", () => {
      const yaml = `key:\tvalue`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("allows colon inside quoted strings", () => {
      const yaml = `key: "value:with:colons"`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("detects colon error on correct line", () => {
      const yaml = `
valid: line
invalid:no_space
another: valid
`;
      const result = validateYamlSyntax(yaml);
      const colonError = result.errors.find((e) =>
        e.message.includes("Colon")
      );
      expect(colonError?.line).toBe(3);
    });

    test("skips validation for list items starting with dash", () => {
      const yaml = `
items:
  - item1
  - item2
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });
  });

  // ============================================================================
  // Edge Cases and Complex Scenarios
  // ============================================================================

  describe("edge cases and complex scenarios", () => {
    test("handles multiple errors in single file", () => {
      const yaml = `
key: "bad quote
  nested: bad indent
another:value no space
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(1);
    });

    test("deduplicates errors on same line and column", () => {
      const yaml = `key:value`;
      const result = validateYamlSyntax(yaml);
      // Multiple validators might flag the same error; it should be deduplicated
      const errorsByLocation = new Set(
        result.errors.map((e) => `${e.line}-${e.column}`)
      );
      expect(errorsByLocation.size).toBe(result.errors.length);
    });

    test("returns errors sorted by line number", () => {
      const yaml = `
key: "unclosed1
root:
  nested: bad
key2:no_space
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      for (let i = 1; i < result.errors.length; i++) {
        expect(result.errors[i].line).toBeGreaterThanOrEqual(
          result.errors[i - 1].line
        );
      }
    });

    test("handles large file without errors", () => {
      let yaml = "";
      for (let i = 0; i < 100; i++) {
        yaml += `item${i}: value${i}\n`;
      }
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("returns fileSize in result", () => {
      const yaml = `key: value`;
      const result = validateYamlSyntax(yaml);
      expect(result.fileSize).toBe(yaml.length);
    });

    test("handles tabs and spaces mixture in comments", () => {
      const yaml = `
# Comment\twith\ttabs
key: value
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("handles Windows line endings (CRLF)", () => {
      const yaml = `key: value\r\nnested:\r\n  subkey: value`;
      const result = validateYamlSyntax(yaml);
      // Should still be valid; CRLF is handled by split('\n')
      expect(result.errors.length).toBeLessThan(2);
    });

    test("handles mixed valid and invalid list items", () => {
      const yaml = `
items:
  - valid
  - "unclosed
  - another
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.message.includes("quote"))).toBe(true);
    });
  });

  // ============================================================================
  // Error Format and Structure Tests
  // ============================================================================

  describe("error format and structure", () => {
    test("error includes required fields", () => {
      const yaml = `key:value`;
      const result = validateYamlSyntax(yaml);
      const error = result.errors[0];
      expect(error).toHaveProperty("line");
      expect(error).toHaveProperty("column");
      expect(error).toHaveProperty("message");
      expect(error).toHaveProperty("type");
    });

    test("error type is one of valid types", () => {
      const yaml = `
key:value
  mixed: indent
"unclosed
`;
      const result = validateYamlSyntax(yaml);
      const validTypes = ["indentation", "syntax", "structure", "delimiter"];
      for (const error of result.errors) {
        expect(validTypes).toContain(error.type);
      }
    });

    test("error line number is positive", () => {
      const yaml = `key:value`;
      const result = validateYamlSyntax(yaml);
      for (const error of result.errors) {
        expect(error.line).toBeGreaterThan(0);
      }
    });

    test("error column number is positive", () => {
      const yaml = `key:value`;
      const result = validateYamlSyntax(yaml);
      for (const error of result.errors) {
        expect(error.column).toBeGreaterThan(0);
      }
    });

    test("error message is non-empty string", () => {
      const yaml = `
key:value
  nested: indent
`;
      const result = validateYamlSyntax(yaml);
      for (const error of result.errors) {
        expect(typeof error.message).toBe("string");
        expect(error.message.length).toBeGreaterThan(0);
      }
    });

    test("context field is included when present", () => {
      const yaml = `
key1: value1
key2:value_no_space
`;
      const result = validateYamlSyntax(yaml);
      const error = result.errors.find((e) => e.type === "syntax");
      expect(error?.context).toBeDefined();
      expect(typeof error?.context).toBe("string");
    });
  });

  // ============================================================================
  // Integration Tests - Realistic YAML Scenarios
  // ============================================================================

  describe("realistic YAML document scenarios", () => {
    test("validates simple configuration file", () => {
      const yaml = `
name: myapp
version: 1.0.0
author: Test Author
description: A test application
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("validates nested configuration with lists", () => {
      const yaml = `
server:
  host: localhost
  port: 8080
  endpoints:
    - /api/users
    - /api/posts
    - /api/comments
database:
  name: mydb
  credentials:
    username: admin
    password: secret
`;
      const result = validateYamlSyntax(yaml);
      expect(result.valid).toBe(true);
    });

    test("detects errors in realistic invalid config", () => {
      const yaml = `
server:
  host localhost
  port: 8080
   bad_indent: value
