import { describe, test, expect, beforeAll, afterAll } from "bun:test";
import { spawnSync } from "bun";
import { mkdir, writeFile, rm } from "fs/promises";
import path from "path";

/**
 * Integration tests for the YAML validator CLI.
 * Tests the CLI interface, file handling, output formatting, and exit codes.
 */

const TEST_DIR = "/tmp/yaml-validator-tests";

/**
 * Helper to run the validator CLI with arguments.
 * Returns exit code, stdout, and stderr.
 */
async function runValidate(
  args: string[]
): Promise<{ exitCode: number; stdout: string; stderr: string }> {
  const process = spawnSync({
    cmd: ["bun", "run", "src/validate.ts", ...args],
    cwd: "/tmp/rp1-evals/f582499a/workspace",
  });

  return {
    exitCode: process.exitCode ?? 1,
    stdout: new TextDecoder().decode(process.stdout),
    stderr: new TextDecoder().decode(process.stderr),
  };
}

describe("validate CLI - Integration Tests", () => {
  beforeAll(async () => {
    // Create test directory
    await mkdir(TEST_DIR, { recursive: true });

    // Create test fixtures
    // Valid YAML file
    await writeFile(
      path.join(TEST_DIR, "valid.yaml"),
      `---
name: Test Config
version: 1.0.0
settings:
  debug: false
  timeout: 30
items:
  - first
  - second
  - third
`
    );

    // Invalid YAML file - bad indentation
    await writeFile(
      path.join(TEST_DIR, "invalid-indent.yaml"),
      `name: Test Config
settings:
  debug: false
   wrong: indent
`
    );

    // Invalid YAML file - unclosed quotes
    await writeFile(
      path.join(TEST_DIR, "invalid-quotes.yaml"),
      `name: "Test Config
version: 1.0.0
`
    );

    // Another valid file
    await writeFile(
      path.join(TEST_DIR, "valid2.yaml"),
      `key: value
nested:
  subkey: subvalue
`
    );

    // Invalid file with multiple errors
    await writeFile(
      path.join(TEST_DIR, "invalid-multiple.yaml"),
      `name: "unclosed
settings:
  bad:indent
items:
  - list
   - wrong
`
    );
  });

  afterAll(async () => {
    // Clean up test directory
    await rm(TEST_DIR, { recursive: true, force: true });
  });

  // ============================================================================
  // Test: Single File Validation - Valid Case
  // ============================================================================

  test("validates single valid YAML file with exit code 0", async () => {
    const filePath = path.join(TEST_DIR, "valid.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain(`Validating: ${filePath}`);
    expect(result.stdout).toContain("✓ Valid");
    expect(result.stdout).toContain("Results: 1 valid, 0 invalid");
  });

  // ============================================================================
  // Test: Single File Validation - Invalid Case
  // ============================================================================

  test("validates single invalid YAML file with exit code 1", async () => {
    const filePath = path.join(TEST_DIR, "invalid-indent.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(1);
    expect(result.stdout).toContain(`Validating: ${filePath}`);
    expect(result.stdout).toContain("✗ Invalid");
    expect(result.stdout).toContain("Line");
    expect(result.stdout).toContain("Column");
    expect(result.stdout).toContain("Results: 0 valid, 1 invalid");
  });

  // ============================================================================
  // Test: Error Output Format Verification
  // ============================================================================

  test("error output includes file path, line number, column, and message", async () => {
    const filePath = path.join(TEST_DIR, "invalid-quotes.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(1);
    // Check that output contains error details
    expect(result.stdout).toContain("Line");
    expect(result.stdout).toContain("Column");
    expect(result.stdout).toMatch(/Line \d+, Column \d+:/);
  });

  // ============================================================================
  // Test: Multiple File Validation - Mixed Valid/Invalid
  // ============================================================================

  test("validates multiple files and reports mixed results", async () => {
