  lineNum: number,
  lines: string[]
): ValidationError[] {
  const errors: ValidationError[] = [];

  if (line.length === 0 || !line[0].match(/\s/)) {
    return errors; // No indentation
  }

  // Check for tabs (not allowed in YAML)
  if (line.includes('\t')) {
    errors.push({
      type: 'INDENTATION_TAB',
      line: lineNum + 1,
      column: 1,
      message: "YAML uses spaces, not tabs",
      content: line
    });
  }

  // Check indentation consistency (should be multiples of 2)
  const leadingSpaces = line.match(/^( *)/)?.[1].length || 0;
  if (leadingSpaces > 0) {
    // Check if indentation is reasonable increment from previous indented line
    let expectedIndent = 0;
    for (let i = lineNum - 1; i >= 0; i--) {
      const prevLine = lines[i];
      const prevTrimmed = prevLine.trim();
      if (prevTrimmed && !prevTrimmed.startsWith('#')) {
        const prevIndent = prevLine.match(/^( *)/)?.[1].length || 0;
        expectedIndent = prevIndent;
        break;
      }
    }

    // Jumping more than 2-4 spaces is usually wrong
    if (expectedIndent > 0) {
      const diff = leadingSpaces - expectedIndent;
      if (diff > 4 || (diff < 0 && Math.abs(diff) > 4)) {
        errors.push({
          type: 'INDENTATION_INCONSISTENT',
          line: lineNum + 1,
          column: leadingSpaces + 1,
          message: "Indentation jump too large from previous line",
          content: line
        });
      }
    }
  }

  return errors;
}

