function validateQuotes(line: string, lineNum: number): ValidationError[] {
  const errors: ValidationError[] = [];

  // For each position, count quotes up to that point
  // This helps detect mismatched quotes
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let escapedNext = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    // Handle escape sequences
    if (escapedNext) {
      escapedNext = false;
      continue;
    }

    if (char === '\\') {
      escapedNext = true;
      continue;
    }

    if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    } else if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
    }
  }

  // If we end with unclosed quotes, report error
  if (inSingleQuote) {
    errors.push({
      type: 'UNCLOSED_QUOTE',
      line: lineNum + 1,
      column: line.lastIndexOf("'") + 1,
      message: "Unclosed single quote",
      content: line
    });
  }

  if (inDoubleQuote) {
    errors.push({
      type: 'UNCLOSED_QUOTE',
      line: lineNum + 1,
      column: line.lastIndexOf('"') + 1,
      message: "Unclosed double quote",
      content: line
    });
  }

  return errors;
}

