import { validateYamlSyntax, type ValidationResult } from "./yaml-validator";

/**
 * Main CLI function for YAML validation.
 * Parses command-line arguments, validates files, and outputs results.
 *
 * @param args - Command-line arguments (file paths)
 * @returns Process exit code (0 for all valid, 1 for any invalid)
 */
async function main(args: string[]): Promise<number> {
  // Get file paths from arguments (skip node and script name)
  const filePaths = args.slice(2);

  // Check if file paths were provided
  if (filePaths.length === 0) {
    console.error("Usage: bun run validate <file1> [file2] ...");
    console.error("Example: bun run validate config.yaml");
    return 1;
  }

  const results: Array<{ path: string; result: ValidationResult }> = [];
  let hasErrors = false;

  // Validate each file
  for (const filePath of filePaths) {
    console.log(`Validating: ${filePath}`);

    try {
      // Read file using Bun.file()
      const file = Bun.file(filePath);
      const exists = await file.exists();

      if (!exists) {
        console.error(`Error: File not found: ${filePath}`);
        hasErrors = true;
        continue;
      }

      const content = await file.text();
      const result = validateYamlSyntax(content, filePath);

      results.push({ path: filePath, result });

      // Print file status
      if (result.valid) {
        console.log("✓ Valid\n");
      } else {
        console.log("✗ Invalid");
        // Print error details
        for (const error of result.errors) {
          console.log(
            `  Line ${error.line}, Column ${error.column}: ${error.message}`
          );
        }
        console.log("");
        hasErrors = true;
      }
    } catch (error) {
      const message =
        error instanceof Error ? error.message : String(error);
      console.error(`Error reading ${filePath}: ${message}`);
      hasErrors = true;
    }
  }

  // Print summary
  const validCount = results.filter((r) => r.result.valid).length;
  const invalidCount = results.filter((r) => !r.result.valid).length;
  const totalCount = results.length;

  if (totalCount > 0) {
    console.log(`Results: ${validCount} valid, ${invalidCount} invalid`);
  }

  // Return exit code
  return hasErrors ? 1 : 0;
}

// Invoke CLI with process.argv
const exitCode = await main(process.argv);
process.exit(exitCode);

