import { describe, test, expect, beforeAll, afterAll } from "bun:test";
import { spawnSync } from "bun";
import { mkdir, writeFile, rm } from "fs/promises";
import path from "path";

/**
 * Integration tests for the YAML validator CLI.
 * Tests the CLI interface, file handling, output formatting, and exit codes.
 */

const TEST_DIR = "/tmp/yaml-validator-tests";

/**
 * Helper to run the validator CLI with arguments.
 * Returns exit code, stdout, and stderr.
 */
async function runValidate(
  args: string[]
): Promise<{ exitCode: number; stdout: string; stderr: string }> {
  const process = spawnSync({
    cmd: ["bun", "run", "src/validate.ts", ...args],
    cwd: "/tmp/rp1-evals/f582499a/workspace",
  });

  return {
    exitCode: process.exitCode ?? 1,
    stdout: new TextDecoder().decode(process.stdout),
    stderr: new TextDecoder().decode(process.stderr),
  };
}

describe("validate CLI - Integration Tests", () => {
  beforeAll(async () => {
    // Create test directory
    await mkdir(TEST_DIR, { recursive: true });

    // Create test fixtures
    // Valid YAML file
    await writeFile(
      path.join(TEST_DIR, "valid.yaml"),
      `---
name: Test Config
version: 1.0.0
settings:
  debug: false
  timeout: 30
items:
  - first
  - second
  - third
`
    );

    // Invalid YAML file - bad indentation
    await writeFile(
      path.join(TEST_DIR, "invalid-indent.yaml"),
      `name: Test Config
settings:
  debug: false
   wrong: indent
`
    );

    // Invalid YAML file - unclosed quotes
    await writeFile(
      path.join(TEST_DIR, "invalid-quotes.yaml"),
      `name: "Test Config
version: 1.0.0
`
    );

    // Another valid file
    await writeFile(
      path.join(TEST_DIR, "valid2.yaml"),
      `key: value
nested:
  subkey: subvalue
`
    );

    // Invalid file with multiple errors
    await writeFile(
      path.join(TEST_DIR, "invalid-multiple.yaml"),
      `name: "unclosed
settings:
  bad:indent
items:
  - list
   - wrong
`
    );
  });

  afterAll(async () => {
    // Clean up test directory
    await rm(TEST_DIR, { recursive: true, force: true });
  });

  // ============================================================================
  // Test: Single File Validation - Valid Case
  // ============================================================================

  test("validates single valid YAML file with exit code 0", async () => {
    const filePath = path.join(TEST_DIR, "valid.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain(`Validating: ${filePath}`);
    expect(result.stdout).toContain("✓ Valid");
    expect(result.stdout).toContain("Results: 1 valid, 0 invalid");
  });

  // ============================================================================
  // Test: Single File Validation - Invalid Case
  // ============================================================================

  test("validates single invalid YAML file with exit code 1", async () => {
    const filePath = path.join(TEST_DIR, "invalid-indent.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(1);
    expect(result.stdout).toContain(`Validating: ${filePath}`);
    expect(result.stdout).toContain("✗ Invalid");
    expect(result.stdout).toContain("Line");
    expect(result.stdout).toContain("Column");
    expect(result.stdout).toContain("Results: 0 valid, 1 invalid");
  });

  // ============================================================================
  // Test: Error Output Format Verification
  // ============================================================================

  test("error output includes file path, line number, column, and message", async () => {
    const filePath = path.join(TEST_DIR, "invalid-quotes.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(1);
    // Check that output contains error details
    expect(result.stdout).toContain("Line");
    expect(result.stdout).toContain("Column");
    expect(result.stdout).toMatch(/Line \d+, Column \d+:/);
  });

  // ============================================================================
  // Test: Multiple File Validation - Mixed Valid/Invalid
  // ============================================================================

  test("validates multiple files and reports mixed results", async () => {
    const file1 = path.join(TEST_DIR, "valid.yaml");
    const file2 = path.join(TEST_DIR, "invalid-indent.yaml");

    const result = await runValidate([file1, file2]);

    expect(result.exitCode).toBe(1); // Exit 1 because one file is invalid
    expect(result.stdout).toContain(`Validating: ${file1}`);
    expect(result.stdout).toContain(`Validating: ${file2}`);
    expect(result.stdout).toContain("✓ Valid");
    expect(result.stdout).toContain("✗ Invalid");
    expect(result.stdout).toContain("Results: 1 valid, 1 invalid");
  });

  // ============================================================================
  // Test: Multiple Files - All Valid
  // ============================================================================

  test("validates multiple valid files with exit code 0", async () => {
    const file1 = path.join(TEST_DIR, "valid.yaml");
    const file2 = path.join(TEST_DIR, "valid2.yaml");

    const result = await runValidate([file1, file2]);

    expect(result.exitCode).toBe(0); // All files valid
    expect(result.stdout).toContain("✓ Valid");
    expect(result.stdout).toContain("Results: 2 valid, 0 invalid");
  });

  // ============================================================================
  // Test: Multiple Files - All Invalid
  // ============================================================================

  test("validates multiple invalid files with exit code 1", async () => {
    const file1 = path.join(TEST_DIR, "invalid-indent.yaml");
    const file2 = path.join(TEST_DIR, "invalid-quotes.yaml");

    const result = await runValidate([file1, file2]);

    expect(result.exitCode).toBe(1);
    expect(result.stdout).toContain("✗ Invalid");
    expect(result.stdout).toContain("Results: 0 valid, 2 invalid");
  });

  // ============================================================================
  // Test: File Not Found Error Handling
  // ============================================================================

  test("handles missing file with error message and exit code 1", async () => {
    const filePath = path.join(TEST_DIR, "nonexistent.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("Error");
    expect(result.stderr).toContain("not found");
  });

  // ============================================================================
  // Test: No Arguments Provided
  // ============================================================================

  test("returns exit code 1 when no files provided", async () => {
    const result = await runValidate([]);

    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("Usage:");
    expect(result.stderr).toContain("validate");
  });

  // ============================================================================
  // Test: Exit Code Correctness for All Valid Files
  // ============================================================================

  test("exit code is 0 when all files are valid", async () => {
    const file1 = path.join(TEST_DIR, "valid.yaml");
    const file2 = path.join(TEST_DIR, "valid2.yaml");

    const result = await runValidate([file1, file2]);

    expect(result.exitCode).toBe(0);
  });

  // ============================================================================
  // Test: Exit Code Correctness for Any Invalid File
  // ============================================================================

  test("exit code is 1 when any file is invalid", async () => {
    const file1 = path.join(TEST_DIR, "valid.yaml");
    const file2 = path.join(TEST_DIR, "valid2.yaml");
    const file3 = path.join(TEST_DIR, "invalid-indent.yaml");

    const result = await runValidate([file1, file2, file3]);

    expect(result.exitCode).toBe(1);
  });

  // ============================================================================
  // Test: Summary Format Validation
  // ============================================================================

  test("summary format shows correct counts of valid and invalid files", async () => {
    const file1 = path.join(TEST_DIR, "valid.yaml");
    const file2 = path.join(TEST_DIR, "invalid-indent.yaml");
    const file3 = path.join(TEST_DIR, "valid2.yaml");

    const result = await runValidate([file1, file2, file3]);

    expect(result.stdout).toMatch(/Results: \d+ valid, \d+ invalid/);
    expect(result.stdout).toContain("Results: 2 valid, 1 invalid");
  });

  // ============================================================================
  // Test: Multiple Errors in Single File
  // ============================================================================

  test("reports multiple errors in single file", async () => {
    const filePath = path.join(TEST_DIR, "invalid-multiple.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(1);
    expect(result.stdout).toContain("✗ Invalid");
    // Should report multiple errors (unclosed quote + indentation)
    const errorLines = result.stdout.split("\n").filter((line) =>
      line.match(/Line \d+, Column \d+:/)
    );
    expect(errorLines.length).toBeGreaterThan(0);
  });

  // ============================================================================
  // Test: Error Line and Column Numbers Are Positive
  // ============================================================================

  test("error messages contain valid line and column numbers", async () => {
    const filePath = path.join(TEST_DIR, "invalid-quotes.yaml");
    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(1);
    // Extract error lines and verify line/column numbers are positive
    const errorPattern = /Line (\d+), Column (\d+):/g;
    const matches = Array.from(result.stdout.matchAll(errorPattern));

    expect(matches.length).toBeGreaterThan(0);

    for (const match of matches) {
      const line = parseInt(match[1], 10);
      const column = parseInt(match[2], 10);

      expect(line).toBeGreaterThan(0);
      expect(column).toBeGreaterThan(0);
    }
  });

  // ============================================================================
  // Test: Consistent Output Format Across Multiple Invocations
  // ============================================================================

  test("output format is consistent across multiple invocations", async () => {
    const filePath = path.join(TEST_DIR, "valid.yaml");

    const result1 = await runValidate([filePath]);
    const result2 = await runValidate([filePath]);

    expect(result1.exitCode).toBe(result2.exitCode);
    expect(result1.stdout).toEqual(result2.stdout);
  });

  // ============================================================================
  // Test: Validation of File with Comments
  // ============================================================================

  test("validates YAML files with comments correctly", async () => {
    const commentedYaml = `# Configuration file
name: Test Config
# Settings section
settings:
  debug: false  # Enable debug mode
`;

    const filePath = path.join(TEST_DIR, "with-comments.yaml");
    await writeFile(filePath, commentedYaml);

    const result = await runValidate([filePath]);

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("✓ Valid");
  });

  // ============================================================================
  // Test: Large Number of Files
  // ============================================================================

  test("handles validation of many files in single command", async () => {
    // Create multiple test files
    const files: string[] = [];

    for (let i = 0; i < 5; i++) {
      const filePath = path.join(TEST_DIR, `batch-${i}.yaml`);
      await writeFile(filePath, `key${i}: value${i}\nnested:\n  sub: value\n`);
      files.push(filePath);
    }

    const result = await runValidate(files);

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("Results: 5 valid, 0 invalid");
  });
});

