     1→/**
     2→ * YAML syntax validator module.
     3→ * Provides lightweight YAML syntax validation without external dependencies.
     4→ */
     5→
     6→/**
     7→ * Represents a single validation error found in YAML content.
     8→ */
     9→export interface YamlError {
    10→  line: number;
    11→  column: number;
    12→  message: string;
    13→  type: "indentation" | "syntax" | "structure" | "delimiter";
    14→  context?: string;
    15→}
    16→
    17→/**
    18→ * Result of validating YAML content.
    19→ */
    20→export interface ValidationResult {
    21→  valid: boolean;
    22→  errors: YamlError[];
    23→  fileSize?: number;
    24→}
    25→
    26→/**
    27→ * Validate YAML content for syntax errors.
    28→ * Checks for common structural issues: indentation, quote matching, delimiters, and key-value syntax.
    29→ *
    30→ * @param content - The YAML file content as a string
    31→ * @param fileName - Optional filename for error context
    32→ * @returns Validation result with error list
    33→ */
    34→export function validateYamlSyntax(
    35→  content: string,
    36→  fileName?: string
    37→): ValidationResult {
    38→  const lines = content.split("\n");
    39→  const errors: YamlError[] = [];
    40→
    41→  // Collect errors from all validation checks
    42→  errors.push(...checkIndentation(lines));
    43→  errors.push(...checkQuoteMatching(lines));
    44→  errors.push(...checkDelimiters(lines));
    45→  errors.push(...checkKeyValueSyntax(lines));
    46→
    47→  // Remove duplicate errors (same line/column)
    48→  const uniqueErrors = Array.from(
    49→    new Map(errors.map((e) => [`${e.line}-${e.column}`, e])).values()
    50→  );
    51→
    52→  // Sort errors by line number
    53→  uniqueErrors.sort((a, b) => a.line - b.line);
    54→
    55→  return {
    56→    valid: uniqueErrors.length === 0,
    57→    errors: uniqueErrors,
    58→    fileSize: content.length,
    59→  };
    60→}
    61→
    62→/**
    63→ * Check indentation consistency throughout the document.
    64→ * Validates that indentation uses either 2-space or 4-space consistently.
    65→ *
    66→ * @param lines - Array of content lines
    67→ * @returns Array of indentation errors
    68→ */
    69→function checkIndentation(lines: string[]): YamlError[] {
    70→  const errors: YamlError[] = [];
    71→  const indentPatterns: Set<number> = new Set();
    72→  let expectedIndent: number | null = null;
    73→
    74→  for (let i = 0; i < lines.length; i++) {
    75→    const line = lines[i];
    76→
    77→    // Skip empty lines and lines with only whitespace
    78→    if (line.trim().length === 0) {
    79→      continue;
    80→    }
    81→
    82→    // Calculate indentation level (spaces at start)
    83→    const match = line.match(/^( *)/);
    84→    if (!match) {
    85→      continue;
    86→    }
    87→
    88→    const indentCount = match[1].length;
    89→
    90→    // Skip lines with no indentation
    91→    if (indentCount === 0) {
    92→      continue;
    93→    }
    94→
    95→    // Determine indent unit (2 or 4 spaces)
    96→    const indentUnit = indentCount % 4 === 0 ? 4 : indentCount % 2 === 0 ? 2 : 0;
    97→
    98→    if (indentUnit === 0) {
    99→      // Invalid indentation (not a multiple of 2 or 4)
   100→      errors.push({
   101→        line: i + 1,
   102→        column: indentCount + 1,
   103→        message: `Invalid indentation: ${indentCount} spaces (must be multiple of 2)`,
   104→        type: "indentation",
   105→        context: line.trim().substring(0, 30),
   106→      });
   107→      continue;
   108→    }
   109→
   110→    indentPatterns.add(indentUnit);
   111→
   112→    // Check if we have mixed indent styles
   113→    if (indentPatterns.size > 1) {
   114→      const patterns = Array.from(indentPatterns).sort();
   115→      errors.push({
   116→        line: i + 1,
   117→        column: indentCount + 1,
   118→        message: `Mixed indentation: found both ${patterns[0]}-space and ${patterns[1]}-space indents`,
   119→        type: "indentation",
   120→        context: line.trim().substring(0, 30),
   121→      });
   122→    }
   123→  }
   124→
   125→  return errors;
   126→}
   127→
   128→/**
   129→ * Check that quotes (single and double) are properly matched.
   130→ *
   131→ * @param lines - Array of content lines
   132→ * @returns Array of quote matching errors
   133→ */
   134→function checkQuoteMatching(lines: string[]): YamlError[] {
   135→  const errors: YamlError[] = [];
   136→
   137→  for (let i = 0; i < lines.length; i++) {
   138→    const line = lines[i];
   139→    let inDouble = false;
   140→    let inSingle = false;
   141→
   142→    for (let col = 0; col < line.length; col++) {
   143→      const char = line[col];
   144→
   145→      // Skip escaped characters
   146→      if (col > 0 && line[col - 1] === "\\") {
   147→        continue;
   148→      }
   149→
   150→      if (char === '"' && !inSingle) {
   151→        inDouble = !inDouble;
   152→      } else if (char === "'" && !inDouble) {
   153→        inSingle = !inSingle;
   154→      }
   155→    }
   156→
   157→    // Check for unclosed quotes at end of line
   158→    if (inDouble) {
   159→      errors.push({
   160→        line: i + 1,
   161→        column: line.length,
   162→        message: 'Unclosed double quote',
   163→        type: "syntax",
   164→        context: line.trim().substring(0, 30),
   165→      });
   166→    }
   167→
   168→    if (inSingle) {
   169→      errors.push({
   170→        line: i + 1,
   171→        column: line.length,
   172→        message: "Unclosed single quote",
   173→        type: "syntax",
   174→        context: line.trim().substring(0, 30),
   175→      });
   176→    }
   177→  }
   178→
   179→  return errors;
   180→}
   181→
   182→/**
   183→ * Validate YAML delimiters (---, ...) appear on their own lines.
   184→ *
   185→ * @param lines - Array of content lines
   186→ * @returns Array of delimiter errors
   187→ */
   188→function checkDelimiters(lines: string[]): YamlError[] {
   189→  const errors: YamlError[] = [];
   190→
   191→  for (let i = 0; i < lines.length; i++) {
   192→    const line = lines[i];
   193→    const trimmed = line.trim();
   194→
   195→    // Check for document start/end markers that aren't on their own line
   196→    if ((trimmed === "---" || trimmed === "...") && line !== trimmed) {
   197→      errors.push({
   198→        line: i + 1,
   199→        column: 1,
   200→        message: `Document delimiter '${trimmed}' must be on its own line`,
   201→        type: "delimiter",
   202→        context: line.trim().substring(0, 30),
   203→      });
   204→    }
   205→
   206→    // Check for malformed delimiters (e.g., ---- or ....)
   207→    if (/^-{4,}/.test(trimmed) || /^\.{4,}/.test(trimmed)) {
   208→      errors.push({
   209→        line: i + 1,
   210→        column: 1,
   211→        message: `Invalid delimiter: '${trimmed.substring(0, 4)}...' (use '---' or '...')`,
   212→        type: "delimiter",
   213→        context: line.trim().substring(0, 30),
   214→      });
   215→    }
   216→  }
   217→
   218→  return errors;
   219→}
   220→
   221→/**
   222→ * Check key-value pair syntax: colons must have space after them.
   223→ *
   224→ * @param lines - Array of content lines
   225→ * @returns Array of key-value syntax errors
   226→ */
   227→function checkKeyValueSyntax(lines: string[]): YamlError[] {
   228→  const errors: YamlError[] = [];
   229→
   230→  for (let i = 0; i < lines.length; i++) {
   231→    const line = lines[i];
   232→    const trimmed = line.trim();
   233→
   234→    // Skip empty lines and special lines
   235→    if (trimmed.length === 0 || trimmed.startsWith("#")) {
   236→      continue;
   237→    }
   238→
   239→    // Skip document markers and list items for now
   240→    if (trimmed.startsWith("---") || trimmed.startsWith("...") || trimmed.startsWith("-")) {
   241→      continue;
   242→    }
   243→
   244→    // Look for colons that aren't followed by space, newline, or quoted content
   245→    for (let col = 0; col < trimmed.length; col++) {
   246→      if (trimmed[col] === ":") {
   247→        const nextChar = trimmed[col + 1];
   248→
   249→        // Colon at end of line or followed by space is OK
   250→        if (col === trimmed.length - 1 || nextChar === " " || nextChar === "\t") {
   251→          continue;
   252→        }
   253→
   254→        // Check if we're inside a quoted string (skip validation)
   255→        let inQuote = false;
   256→        for (let j = 0; j < col; j++) {
   257→          if (trimmed[j] === '"' || trimmed[j] === "'") {
   258→            inQuote = !inQuote;
   259→          }
   260→        }
   261→
   262→        if (!inQuote && nextChar !== undefined) {
   263→          errors.push({
   264→            line: i + 1,
   265→            column: col + 1,
   266→            message: "Colon must be followed by space in YAML",
   267→            type: "syntax",
   268→            context: trimmed.substring(0, 40),
   269→          });
   270→        }
   271→      }
   272→    }
   273→  }
   274→
   275→  return errors;
   276→}
