     3→/**
     4→ * Main CLI function for YAML validation.
     5→ * Parses command-line arguments, validates files, and outputs results.
     6→ *
     7→ * @param args - Command-line arguments (file paths)
     8→ * @returns Process exit code (0 for all valid, 1 for any invalid)
     9→ */
    10→async function main(args: string[]): Promise<number> {
    11→  // Get file paths from arguments (skip node and script name)
    12→  const filePaths = args.slice(2);
    13→
    14→  // Check if file paths were provided
    15→  if (filePaths.length === 0) {
    16→    console.error("Usage: bun run validate <file1> [file2] ...");
    17→    console.error("Example: bun run validate config.yaml");
    18→    return 1;
    19→  }
    20→
    21→  const results: Array<{ path: string; result: ValidationResult }> = [];
    22→  let hasErrors = false;
    23→
    24→  // Validate each file
    25→  for (const filePath of filePaths) {
    26→    console.log(`Validating: ${filePath}`);
    27→
    28→    try {
    29→      // Read file using Bun.file()
    30→      const file = Bun.file(filePath);
    31→      const exists = await file.exists();
    32→
    33→      if (!exists) {
    34→        console.error(`Error: File not found: ${filePath}`);
    35→        hasErrors = true;
    36→        continue;
    37→      }
    38→
    39→      const content = await file.text();
    40→      const result = validateYamlSyntax(content, filePath);
    41→
    42→      results.push({ path: filePath, result });
    43→
    44→      // Print file status
    45→      if (result.valid) {
    46→        console.log("✓ Valid\n");
    47→      } else {
    48→        console.log("✗ Invalid");
    49→        // Print error details
    50→        for (const error of result.errors) {
    51→          console.log(
    52→            `  Line ${error.line}, Column ${error.column}: ${error.message}`
    53→          );
    54→        }
    55→        console.log("");
    56→        hasErrors = true;
    57→      }
    58→    } catch (error) {
    59→      const message =
    60→        error instanceof Error ? error.message : String(error);
    61→      console.error(`Error reading ${filePath}: ${message}`);
    62→      hasErrors = true;
    63→    }
    64→  }
    65→
    66→  // Print summary
    67→  const validCount = results.filter((r) => r.result.valid).length;
    68→  const invalidCount = results.filter((r) => !r.result.valid).length;
    69→  const totalCount = results.length;
    70→
    71→  if (totalCount > 0) {
    72→    console.log(`Results: ${validCount} valid, ${invalidCount} invalid`);
    73→  }
    74→
    75→  // Return exit code
    76→  return hasErrors ? 1 : 0;
    77→}
    78→
    79→// Invoke CLI with process.argv
    80→const exitCode = await main(process.argv);
    81→process.exit(exitCode);
    82→

